// src/akili/experts/afya/engine/knowledge/labs/glucose.ts
function categorizeGlucose(value, context = "unknown") {
  if (value < 3) return "hypo_severe";
  if (value < 4) return "hypo_mild";
  if (value >= 22) return "critical_high";
  if (value >= 16) return "very_high";
  switch (context) {
    case "fasting":
      if (value < 5.6) return "normal";
      if (value < 7) return "prediabetic";
      return "diabetic_range";
    case "pregnancy_fasting":
      if (value < 5.1) return "normal";
      return "diabetic_range";
    // GDM threshold met
    case "pregnancy_post_meal":
      if (value < 8.5) return "normal";
      return "diabetic_range";
    case "post_meal":
      if (value < 7.8) return "normal";
      if (value < 11.1) return "prediabetic";
      return "diabetic_range";
    case "random":
    case "unknown":
    default:
      if (value < 7.8) return "normal";
      if (value < 11.1) return "prediabetic";
      return "diabetic_range";
  }
}
