// src/akili/experts/fasihi/engine/learn/morph.ts
var SUBJ = {
  "1sg": "ni",
  "2sg": "u",
  "3sg": "a",
  "1pl": "tu",
  "2pl": "m",
  "3pl": "wa"
};
var TENSE = {
  present: "na",
  past: "li",
  future: "ta",
  perfect: "me",
  habitual: "hu"
};
var NEG_SUBJ = {
  "1sg": "si",
  "2sg": "hu",
  "3sg": "ha",
  "1pl": "hatu",
  "2pl": "ham",
  "3pl": "hawa"
};
function conjugate(root, opts) {
  const { person, tense, negative } = opts;
  if (!negative) {
    return `${SUBJ[person]}${TENSE[tense]}${root}`;
  }
  const neg = NEG_SUBJ[person];
  switch (tense) {
    case "present":
    case "habitual": {
      const stem = root.endsWith("a") ? root.slice(0, -1) + "i" : root;
      return `${neg}${stem}`;
    }
    case "past":
      return `${neg}ku${root}`;
    // sikusoma
    case "perfect":
      return `${neg}ja${root}`;
    // sijasoma
    case "future":
      return `${neg}ta${root}`;
  }
}
var PRONOUN = {
  "1sg": "mimi",
  "2sg": "wewe",
  "3sg": "yeye",
  "1pl": "sisi",
  "2pl": "ninyi",
  "3pl": "wao"
};
var PERSON_LABEL = {
  "1sg": ["mimi", "I"],
  "2sg": ["wewe", "you"],
  "3sg": ["yeye", "he/she"],
  "1pl": ["sisi", "we"],
  "2pl": ["ninyi", "you (pl)"],
  "3pl": ["wao", "they"]
};
var ORDER = ["1sg", "2sg", "3sg", "1pl", "2pl", "3pl"];
function paradigm(root, tense, negative = false) {
  return ORDER.map((person) => ({
    person,
    pronoun: PRONOUN[person],
    sw: PERSON_LABEL[person][0],
    form: conjugate(root, { person, tense, negative })
  }));
}

