function tokens3(s) {
  return norm7(s).split(" ").filter(Boolean);
}
function score3(entry, qTokens, qNorm) {
  let s = 0;
  for (const c of entry.cues) {
    if (hasCue4(qNorm, c)) s += 2;
    else if (qTokens.includes(c)) s += 1;
  }
  return s;
}
function bestEntry3(text) {
  const qNorm = norm7(text);
  const qTokens = tokens3(text);
  let best = KB3[0];
  let bestScore = -1;
  for (const e of KB3) {
    const s = score3(e, qTokens, qNorm);
    if (s > bestScore) {
      best = e;
      bestScore = s;
    }
  }
  return { entry: best, score: bestScore };
}
var elimuExpert = {
  id: "elimu-msingi",
  domain: "elimu",
  label: "Elimu",
  match(q) {
    return cueScore4(q.text ?? "", ELIMU_CUES);
  },
  answer(q) {
    const { entry, score: s } = bestEntry3(q.text ?? "");
    const confidence = s >= 4 ? "high" : s >= 2 ? "medium" : "low";
    return {
      domain: "elimu",
      expert: elimuExpert.id,
      text: entry.en ? { sw: entry.sw, en: entry.en } : { sw: entry.sw },
      confidence,
      sources: [...entry.sources, { label: "Akili KB \u2014 Elimu", ref: "Laetoli" }],
      data: { entry: entry.id, score: s }
    };
  }
};

